 async function copyResponse(text){try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(String(text||""));return}const el=document.createElement("textarea");el.value=String(text||"");el.style.position="fixed";el.style.opacity="0";document.body.appendChild(el);el.select();document.execCommand("copy");el.remove()}catch{setError("Copy failed. Please select the response text manually.")}}
